// Basisklasse mit Angular-Funktionen braucht einen eigenen Dekorator
@Directive()
export abstract class BaseListComponent<T> {
  selected = signal<T | undefined>(undefined);
  select(item: T) { this.selected.set(item); }
  isSelected(item: T) { return item === this.selected(); }
}

@Component({ selector: 'customer-list', templateUrl: './customer-list.component.html' })
export class CustomerListComponent extends BaseListComponent<Customer> {
  // erbt selected, select, isSelected
}

// Probleme:
// - Template und Styles werden nicht geerbt, nur Klassenlogik
// - Konstruktor-Parameter der Basis müssen per super(...) durchgereicht werden
// - Jede Änderung an BaseListComponent trifft alle Listen der Anwendung
// - Eine zweite Basisklasse (z. B. für Sortierung) ist nicht möglich

// Gemeinsames Verhalten in einer eigenen Klasse, ohne providedIn
@Injectable()
export class Selection<T> {
  readonly selected = signal<T | undefined>(undefined);
  select(item: T) { this.selected.set(item); }
  isSelected(item: T) { return item === this.selected(); }
}

@Component({
  selector: 'customer-list', templateUrl: './customer-list.component.html',
  providers: [Selection]             // jede Liste bekommt ihre eigene Instanz
})
export class CustomerListComponent {
  readonly selection = inject<Selection<Customer>>(Selection);
}

