// Ersetzt das Muster:
//   selected = signal<Customer | undefined>(undefined);
//   effect(() => this.selected.set(this.customers()[0]));   // effect setzt Signal

selected = linkedSignal<Customer[], Customer | undefined>({
  // source: was beobachtet wird
  source: this.customers,

  // computation: Angular ruft sie auf, wenn sich source ändert
  computation: (newList, previous) => {
    // previous ist beim ersten Lauf undefined,
    // danach { source: alte Liste, value: bisherige Auswahl }
    const keep = newList.find(c => c.id === previous?.value?.id);
    return keep ?? newList[0];    // Auswahl behalten, sonst erstes Element
  },

  // optional: equal: (a, b) => a?.id === b?.id
});

